import{_ as o,o as t,c as a,an as i}from"./chunks/framework.ChljUWQy.js";const h=JSON.parse('{"title":"MAGEMin_py","description":"","frontmatter":{},"headers":[],"relativePath":"MAGEMin_py/MAGEMin_py.md","filePath":"MAGEMin_py/MAGEMin_py.md","lastUpdated":null}'),n={name:"MAGEMin_py/MAGEMin_py.md"};function r(c,e,d,s,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="MAGEMin_py" tabindex="-1">MAGEMin_py <a class="header-anchor" href="#MAGEMin_py" aria-label="Permalink to &quot;MAGEMin_py {#MAGEMin_py}&quot;">​</a></h1><p><code>MAGEMin_py</code> is a Python interface to <code>MAGEMin</code>, the Gibbs energy minimization library written in <code>C</code>. It allows computing the most stable phase equilibrium for a given bulk-rock composition, pressure and temperature directly from <code>Python</code>, so that <code>MAGEMin</code> can be combined with the scientific <code>Python</code> ecosystem.</p><p><code>MAGEMin_py</code> is developed by <a href="https://clr.geology.cz/people/dr-ondrej-lexa" target="_blank" rel="noreferrer">Ondrej Lexa</a> (Czech Geological Survey). It wraps the official minimal <code>C</code> API of <code>MAGEMin</code> and is distributed as the <code>magemin</code> package.</p><div class="tip custom-block"><p class="custom-block-title">Info</p><ul><li><p>Source code, installation instructions, documentation and examples are available in the <code>MAGEMin_py</code> repository: <a href="https://github.com/ondrolexa/MAGEMin_py" target="_blank" rel="noreferrer">https://github.com/ondrolexa/MAGEMin_py</a></p></li><li><p><code>MAGEMin_py</code> is maintained independently of <code>MAGEMin</code>, <code>MAGEMin_C.jl</code> and <code>MAGEMinApp.jl</code>. For questions, issues and feature requests regarding the <code>Python</code> interface, please use its own repository.</p></li></ul></div><h2 id="Where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#Where-to-start" aria-label="Permalink to &quot;Where to start {#Where-to-start}&quot;">​</a></h2><ul><li><p>For a <code>Python</code> workflow, follow the installation and quickstart sections of the <a href="https://github.com/ondrolexa/MAGEMin_py" target="_blank" rel="noreferrer"><code>MAGEMin_py</code> repository</a>.</p></li><li><p>The thermodynamic databases, phases and end-members that <code>MAGEMin</code> provides are described in the <a href="./../database">Databases information</a> page.</p></li><li><p>For a <code>Julia</code> workflow, see <a href="./../MAGEMin_C/MAGEMin_C">MAGEMin_C.jl</a>. For a graphical interface in the web browser, see <a href="./../MAGEMinApp/MAGEMinApp">MAGEMinApp.jl</a>.</p></li></ul>',6)])])}const _=o(n,[["render",r]]);export{h as __pageData,_ as default};
